package com.printflow.enquiry;
import com.printflow.identity.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.util.*;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
@RestController
public class IntakeController {
 public record Revision(@Min(0) long revision,@Size(max=900) String comment,UUID reviewerId){}
 public static final String REJECTION="We are sorry, but J.D.Printex is unable to fulfil this printing enquiry at this time. Please contact our team by phone to discuss the requirements and possible alternatives before submitting a new enquiry.";
 private final CustomerSetup customerSetup;private final ProjectNotifications notifications;private final JdbcTemplate db;private final CustomerMail mail;
 public IntakeController(JdbcTemplate db,CustomerMail mail,ProjectNotifications notifications,CustomerSetup customerSetup){this.customerSetup=customerSetup;this.notifications=notifications;this.db=db;this.mail=mail;}
 private void reviewer(StaffPrincipal u){if(!Set.of("OWNER","DESIGNER").contains(u.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 @GetMapping("/api/v1/design/intake") public ResponseEntity<?> queue(@AuthenticationPrincipal StaffPrincipal u){reviewer(u);return response(db.queryForList("select id,customer_name,product_code,quantity,notes,to_char(requested_date,'YYYY-MM-DD') as requested_date,revision from enquiries where status='NEW' and (? or designer_id is null or designer_id=?) order by created_at,id limit 100",u.role().equals("OWNER"),u.id()));}
 @PostMapping("/api/v1/design/intake/{id}/accept") @Transactional public ResponseEntity<?> accept(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id,@Valid @RequestBody Revision input){reviewer(u);var rows=db.queryForList("select status,revision,designer_id from enquiries where id=? for update",id);if(rows.isEmpty())throw new NoSuchElementException();var e=rows.getFirst();if(u.role().equals("DESIGNER")&&e.get("designer_id")!=null&&!u.id().equals(e.get("designer_id")))throw new NoSuchElementException();if(!"NEW".equals(e.get("status"))||((Number)e.get("revision")).longValue()!=input.revision())throw new ResponseStatusException(HttpStatus.CONFLICT,"Intake changed; refresh first");UUID reviewer=input.reviewerId()==null?u.id():input.reviewerId();if(!u.role().equals("OWNER")&&!reviewer.equals(u.id()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);
  var reviewers=db.queryForList("select role from staff_users where id=? and enabled and role in ('OWNER','DESIGNER')",reviewer);if(reviewers.isEmpty())throw new IllegalArgumentException("Choose an owner or designer for intake review");String reviewRole=reviewers.getFirst().get("role").toString();db.update("update enquiries set status='REVIEWING',intake_accepted_by=?,intake_accepted_at=now(),designer_id=case when ?='DESIGNER' then ? else designer_id end,assigned_staff_id=case when ?='OWNER' and assigned_staff_id is null then ? else assigned_staff_id end,revision=revision+1,updated_at=now() where id=?",u.id(),reviewRole,reviewer,reviewRole,reviewer,id);db.update("insert into enquiry_events(id,enquiry_id,event_type,from_status,to_status) values(?,?,'INTAKE_ACCEPTED','NEW','REVIEWING')",UUID.randomUUID(),id);db.update("insert into work_events(id,enquiry_id,actor_id,kind,message) values(?,?,?,'INTAKE',?)",UUID.randomUUID(),id,u.id(),"The team accepted the enquiry for review"+(input.comment()==null||input.comment().isBlank()?"":": "+input.comment().trim()));db.update("insert into lead_activities(id,enquiry_id,actor_id,action,details) values(?,?,?,'INTAKE_ACCEPTED',?)",UUID.randomUUID(),id,u.id(),"Reviewer: "+reviewer+". "+(input.comment()==null?"":input.comment().trim()));String access=customerSetup.prepare(id);notifications.customer(id,"INTAKE",id,"Your enquiry has been accepted for review. The team is preparing your quotation.\n\n"+access);notifications.team(id,"INTAKE",id,"The enquiry has been accepted for review. Customer account access instructions were sent privately to the customer.");return response(Map.of("code","INTAKE_ACCEPTED"));}
 @PostMapping("/api/v1/design/intake/{id}/reject") @Transactional public ResponseEntity<?> reject(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id,@Valid @RequestBody Revision input){reviewer(u);var rows=db.queryForList("select status,revision,designer_id,email,public_id,customer_user_id from enquiries where id=? for update",id);if(rows.isEmpty())throw new NoSuchElementException();var e=rows.getFirst();if(u.role().equals("DESIGNER")&&e.get("designer_id")!=null&&!u.id().equals(e.get("designer_id")))throw new NoSuchElementException();if(!"NEW".equals(e.get("status"))||((Number)e.get("revision")).longValue()!=input.revision())throw new ResponseStatusException(HttpStatus.CONFLICT,"Intake changed; refresh first");String explanation=input.comment()==null||input.comment().isBlank()?REJECTION:"We are unable to proceed with this enquiry. "+input.comment().trim();db.update("update enquiries set status='CLOSED',closure_kind='REJECTED',closure_message=?,follow_up_at=null,next_action=null,revision=revision+1,updated_at=now() where id=?",explanation,id);db.update("insert into enquiry_events(id,enquiry_id,event_type,from_status,to_status) values(?,?,'REJECTED','NEW','CLOSED')",UUID.randomUUID(),id);db.update("insert into work_events(id,enquiry_id,actor_id,kind,message) values(?,?,?,'REJECTED',?)",UUID.randomUUID(),id,u.id(),explanation);String notification=mail.queueRejection((UUID)e.get("customer_user_id"),id,e.get("email").toString(),e.get("public_id").toString(),explanation);db.update("insert into lead_activities(id,enquiry_id,actor_id,action,details) values(?,?,?,'INTAKE_REJECTED',?)",UUID.randomUUID(),id,u.id(),explanation);return response(Map.of("code","REJECTED","notification",notification,"deliveryEnabled",mail.deliveryEnabled()));}
 @PostMapping("/api/v1/owner/enquiries/{id}/dismiss") @Transactional public ResponseEntity<?> dismiss(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id,@Valid @RequestBody Revision input){if(!u.role().equals("OWNER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN);var rows=db.queryForList("select status,revision,closure_kind,email,public_id,customer_user_id from enquiries where id=? for update",id);if(rows.isEmpty())throw new NoSuchElementException();var e=rows.getFirst();if("REMOVED".equals(e.get("closure_kind")))return response(Map.of("code","ALREADY_REMOVED"));if(((Number)e.get("revision")).longValue()!=input.revision())throw new ResponseStatusException(HttpStatus.CONFLICT,"Enquiry changed; refresh first");
  boolean agreed=db.queryForObject("select exists(select 1 from quote_versions where enquiry_id=? and state='ACCEPTED')",Boolean.class,id);
  String explanation=agreed?"The owner has cancelled and archived this work. Please contact J.D.Printex by phone to discuss the cancellation, any agreed payments and possible alternatives. Your agreement and review history are retained.":REJECTION;
  db.update("update enquiries set status='CLOSED',closure_kind='REMOVED',closure_message=?,follow_up_at=null,next_action=null,revision=revision+1,updated_at=now() where id=?",explanation,id);db.update("insert into enquiry_events(id,enquiry_id,event_type,from_status,to_status) values(?,?,'REMOVED',?,'CLOSED')",UUID.randomUUID(),id,e.get("status"));db.update("insert into work_events(id,enquiry_id,actor_id,kind,message) values(?,?,?,'REMOVED',?)",UUID.randomUUID(),id,u.id(),explanation);db.update("insert into lead_activities(id,enquiry_id,actor_id,action,details) values(?,?,?,'OWNER_DISMISSED','Archived from queue with standard customer explanation and notification')",UUID.randomUUID(),id,u.id());String notification=mail.queueRejection((UUID)e.get("customer_user_id"),id,e.get("email").toString(),e.get("public_id").toString(),explanation);return response(Map.of("code","REMOVED","notification",notification,"deliveryEnabled",mail.deliveryEnabled()));
 }
 public record Selected(@NotNull UUID id,@Min(0) long revision){}
 public record Bulk(@NotEmpty @Size(max=100) List<@Valid Selected> enquiries){}
 public record Preserve(@NotNull UUID preserveId){}
 @PostMapping("/api/v1/owner/enquiries/dismiss-selected") @Transactional public ResponseEntity<?> bulk(@AuthenticationPrincipal StaffPrincipal u,@Valid @RequestBody Bulk input){if(!u.role().equals("OWNER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN);int removed=0;for(var item:input.enquiries().stream().sorted(Comparator.comparing(Selected::id)).toList()){dismiss(u,item.id(),new Revision(item.revision(),null,null));removed++;}return response(Map.of("removed",removed,"deliveryEnabled",mail.deliveryEnabled(),"notification",mail.available()?"QUEUED":"NOT_CONFIGURED"));}
 @PostMapping("/api/v1/owner/enquiries/archive-except") @Transactional public ResponseEntity<?> older(@AuthenticationPrincipal StaffPrincipal u,@Valid @RequestBody Preserve input){if(!u.role().equals("OWNER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN);db.execute("lock table enquiries in share row exclusive mode");UUID latest=input.preserveId();if(!db.queryForObject("select exists(select 1 from enquiries where id=? and coalesce(closure_kind,'')<>'REMOVED')",Boolean.class,latest))throw new ResponseStatusException(HttpStatus.CONFLICT,"The enquiry to preserve is unavailable");var older=db.queryForList("select id,revision from enquiries where id<>? and coalesce(closure_kind,'')<>'REMOVED' order by id",latest);if(older.size()>5000)throw new ResponseStatusException(HttpStatus.CONFLICT,"Use a smaller reviewed batch");for(var item:older)dismiss(u,(UUID)item.get("id"),new Revision(((Number)item.get("revision")).longValue(),null,null));return response(Map.of("removed",older.size(),"preserved",latest,"deliveryEnabled",mail.deliveryEnabled()));}
 private ResponseEntity<?> response(Object value){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(value);}
}
